export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  // Original receipt per idempotency scope (tenant, key). The scope is JSON-encoded so
  // distinct (tenant, key) pairs can never collide.
  readonly #byScope = new Map<string, Receipt>();
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // No await between the lookup and the commit below: check-and-debit is atomic, so
    // concurrent calls for the same tenant/key observe each other's debit.
    const scope = JSON.stringify([tenant, key]);
    const original = this.#byScope.get(scope);
    if (original) {
      if (original.cents !== cents) throw new Error('key conflict');
      return original;
    }
    const receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    this.#byScope.set(scope, receipt);
    return receipt;
  }
}
EOF
